public interface ICustomer { decimal Balance { get; } }
public abstract class CustomerRole : ICustomer {
    public required CustomerCore Core { get; init; }
    public decimal Balance => Core.Balance;               // role forwards core operations
}
public sealed class CustomerCore : ICustomer {
    private readonly Dictionary<Type, CustomerRole> _roles = new();
    public decimal Balance { get; set; }
    public T AddRole<T>() where T : CustomerRole, new() { var r = new T { Core = this }; _roles[typeof(T)] = r; return r; }
    public T? GetRole<T>() where T : CustomerRole => _roles.TryGetValue(typeof(T), out var r) ? (T)r : null;
}
public sealed class BorrowerRole : CustomerRole { public decimal Limit { get; set; } }
